import{_ as t,o,c as n,a2 as s}from"./chunks/framework.BXzK3EA4.js";const r="/assets/a92effb362f1844f.Cj2tn-uc.png",i="/assets/cd508fecb1f3bf52.DKfL7TkK.png",a="/assets/9d9b19ce205292f8.BtdUl67y.png",p="/assets/9fe98183ff5ea333.D2uoSAvm.png",c="/assets/53803d7eeeb4625b.DdBqv908.png",l="/assets/7c7eb9c74d57bb44.CQbBdbEP.png",d="/assets/5902fe0a1ff67c70.Cs5NnuNh.png",h="/assets/77d665cec452efed.CiMGf39f.png",m="/assets/2668b23ddc7729fa.Dph7UO8M.png",C=JSON.parse('{"title":"Change the remote port number in Windows","description":"","frontmatter":{"title":"Change the remote port number in Windows"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/windows/change-the-remote-port-number-in-windows.md","filePath":"operations-knowledge-base/operating-system/windows/change-the-remote-port-number-in-windows.md","lastUpdated":1794292919000}'),u={name:"operations-knowledge-base/operating-system/windows/change-the-remote-port-number-in-windows.md"};function g(f,e,w,_,b,y){return o(),n("div",null,[...e[0]||(e[0]=[s('<p><strong>The remote port number for Windows systems is between 1024 and 65535, and you can choose any port within this range.</strong></p><p>1.To access the Registry Editor, please follow these steps after logging into the system: Press the Win key (Windows logo key) + R to open the Run dialog box. Type &quot;regedit&quot; and press Enter, or open Windows PowerShell and enter the &quot;regedit&quot; command</p><p><img src="'+r+'" alt=""></p><p>2.Open the following path：HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Control\\Terminal Server\\Wds\\rdpwd\\Tds\\tcp</p><p>Double-click or right-click on &quot;PortNumber&quot; to modify it. Change the default value of 3389 to the desired port of your choice (within the range of 1023-65535, preferably avoiding commonly used ports). Click OK to save the changes.</p><p><img src="'+i+'" alt=""></p><p>3.Next, open the following path: HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Control\\Terminal Server\\WinStations\\RDP-Tcp</p><p>Double-click or right-click on &quot;PortNumber&quot; and modify to the same port as mentioned above (the one you want to change to). Click OK to confirm the changes.</p><p><img src="'+a+'" alt=""></p><p>4.Click on &quot;Server Manager&quot; and then click on &quot;Computer Management&quot;. In the pop-up window, select &quot;Services and Applications&quot; on the left-hand side, then choose &quot;Services&quot;. Find &quot;Remote Desktop Service&quot; in the list, right-click on it, and select &quot;Restart&quot;. The port number change will take effect after restart.</p><p>(Alternatively, you can choose to restart the system for the port changes to take effect.)</p><p><img src="'+p+'" alt=""></p><p><img src="'+c+'" alt=""></p><ul><li><p>If the user&#39;s computer firewall is disabled, they can now connect via Remote Desktop from another computer.</p></li><li><p>Usually, for security reasons, it is recommended to keep the firewall enabled. Therefore, it is necessary to modify the inbound rules of the firewall as well.</p></li></ul><p>5.Right-click on the network icon in the lower-right corner - Open Network and Sharing Center - Windows Firewall - Advanced Settings - Inbound Rules - New Rule - Select Port - Enter the port to be allowed - Allow the connection - Check all three network profiles by default - Enter a description - Finish.</p><p><img src="'+l+'" alt=""></p><p><img src="'+d+'" alt=""></p><p>6.The port forwarding is successful, and you can now connect with the new remote port number.</p><p><img src="'+h+'" alt=""></p><p>7.To test remote access, simply add the new remote port number after the remote address to establish a connection.</p><p><img src="'+m+'" alt=""></p>',21)])])}const S=t(u,[["render",g]]);export{C as __pageData,S as default};
